export const NEWS = { us: {}, jp: {} };
export const OPENING = { us: {}, jp: {} };
for (const row of ARTICLES) {
  const p = PRESS_IMAGES[row.imageId];
  const { macro, ...article } = row;
  NEWS[row.country][row.year] = Object.freeze({
    ...article, image: p.image, imageAlt: p.caption, imageCredit: p.artist,
    imageDate: p.date, imageSource: p.page, imageLicense: p.license,
    imageLicenseUrl: p.licenseUrl, imageSha256: p.sha256,
    imageCaption: (row.imageKind === 'event' ? '事件相关实拍：' : '资料照片：') + p.caption,
    imageRelation: row.imageKind === 'event' ? '同一事件的实拍影像；拍摄日期单独标明。' : '与主题相关的档案背景图，不是本条事件现场。',
  });
  OPENING[row.country][row.year + 1] = Object.freeze({
    year: row.year + 1, text: macro, asOf: row.year + '-12-31',
    sourceUrl: row.sourceUrl, sourceTitle: row.sourceTitle,
    sourcePublishedAt: row.sourcePublishedAt, sourceTiming: row.sourceTiming,
    newsId: row.id, newsYear: row.year, kind: 'editorial-prior-year-context',
  });
}
for (const country of ['us', 'jp']) { Object.freeze(NEWS[country]); Object.freeze(OPENING[country]); }
Object.freeze(NEWS); Object.freeze(OPENING);
